// The fonts a text clip can use (lib/video/text). Each is a TrueType file in
// public/fonts, loaded by the preview with @font-face (app/globals.css, the
// CSS family fontFamily gives) and handed to ffmpeg's drawtext by the export,
// so no system font is involved. All are SIL Open Font License 1.1 or Apache
// 2.0; each licence text sits beside its font (`licenceFile`), all listed in
// public/fonts/THIRD_PARTY_FONTS.md. Files are the Google Fonts static
// instances, unmodified (no subsetting by us: a Reserved Font Name forbids
// shipping a modified copy under it); the 37 added after the first 13 are the
// Latin files fonts.gstatic.com serves, about 5 MB for all 50.
//
// 50 fonts, each with one `mood` from FONT_MOODS (the picker's filter chips)
// and a `style` saying what it looks like. Eight are Elegant, seven of them
// sweeping scripts with long swashes (Great Vibes, Dancing Script,
// Parisienne, Tangerine, Monsieur La Doulaise, Sacramento, Alex Brush): their
// `pad` and `line`, taken from the ink like every font's, keep the swashes
// inside the box (Monsieur La Doulaise's pad is over a font size).
//
// The text box is worked out without measuring anything at run time, the same
// numbers in the browser and on the server: each font carries its advance
// widths (`advances`, in font units, one per character of CHARSET, read from
// the font's hmtx table) and its line metrics, all taken from the font file
// once when it was added (lib/video/fonts.test.ts reads the files again and
// checks every number):
// - `ascent`: where the baseline sits below the top of a line's slot, the
//   tallest of the font's ascender and the ink of CHARSET's glyphs, plus half of
//   any extra space `line` adds.
// - `line`: a line's height, the font's ascender plus descender (or its ink,
//   whichever is taller) rounded up to a twentieth, at least 1.2.
// - `pad`: the padding round the text, 0.25 or the most any CHARSET glyph's ink
//   reaches past its advance (left or right) rounded up to a twentieth.
// - `other`: the advance used for a character outside CHARSET, the mean of the
//   font's A-Z and a-z.
// All are fractions of the font size except `advances` and `other`, which are
// in units of `upm` (units per em). Mono, Geist Mono Bold, is the font text
// clips had before fonts could be chosen: a clip with no `font` uses it.
//
// Every font has a glyph for each printable ASCII character (letters, digits
// and punctuation) but Orbitron's "^". Bangers, Creepster, Nosifer, Bungee,
// Graduate, Luckiest Guy, Eater and Butcherman are caps-only designs: their
// lower case letters are capitals too, so the text is kept as typed and shows
// in capitals (Amatic SC and Metal Mania draw lower case as small capitals).
// Press Start 2P and VT323 are monospaced pixel fonts. All work with any text;
// they just look that way.

/** The font picker's filters, in the order its chips show them; each font has one. */
export const FONT_MOODS = ["Clean", "Bold", "Happy", "Fun", "Elegant", "Handwritten", "Retro", "Tech", "Scary", "Creepy"] as const
export type FontMood = (typeof FONT_MOODS)[number]

export type TextFont = {
  id: string
  name: string
  mood: FontMood
  /** What it looks like, shown under its name in the font picker. */
  style: string
  /** The font file, in public/fonts. */
  file: string
  licence: "OFL-1.1" | "Apache-2.0"
  /** The licence text, in public/fonts. */
  licenceFile: string
  upm: number
  ascent: number
  line: number
  pad: number
  other: number
  advances: number[]
}

/** The characters `advances` covers: printable ASCII, Latin-1 and a few typographic marks. */
export const CHARSET = (() => {
  let s = ""
  for (let c = 32; c <= 126; c++) s += String.fromCharCode(c)
  for (let c = 160; c <= 255; c++) s += String.fromCharCode(c)
  return s + "‘’“”–—…•€"
})()

